// Shared by every script. The document arrives as a JSON string; patches are built up as plain objects.
const S = JSON.parse(state);
const E = S.packages.engine;
const T = E.utilities.time.properties.state;
const DT = Math.min(Math.max(T.delta, 0.001), 0.05);
const patch = {};
const X = {};   // what one section of the frame tells a later one, without going through the document
const node = path => {
	let n = patch;
	for (const k of path.split('.')) { n.packages = n.packages || {}; n = n.packages[k] = n.packages[k] || {}; }
	return n;
};
const put = (path, data) => {
	const n = node(path);
	n.properties = n.properties || {}; n.properties.meta = n.properties.meta || {};
	n.properties.meta.data = Object.assign(n.properties.meta.data || {}, data);
};
const comp = (path, name, data, content) => {
	const n = node(path);
	n.utilities = n.utilities || {};
	const u = n.utilities[name] = n.utilities[name] || {};
	if (data) { u.properties = u.properties || {}; u.properties.data = Object.assign(u.properties.data || {}, data); }
	if (content !== undefined) u.content = content;
};
const get = path => {
	let n = S;
	for (const k of path.split('.')) { n = n.packages && n.packages[k]; if (!n) return null; }
	return n;
};
const dat = path => { const n = get(path); return n && n.properties && n.properties.meta ? n.properties.meta.data : null; };
const done = () => Object.keys(patch).length ? JSON.stringify(patch) : undefined;

const len = v => Math.hypot(v[0], v[1], v[2]);
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const norm = a => { const l = len(a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const wrap = a => { while (a > Math.PI) a -= 2 * Math.PI; while (a < -Math.PI) a += 2 * Math.PI; return a; };
const heading = (yaw, pitch) => [-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch)];
const hash = x => { const s = Math.sin(x * 12.9898 + 78.233) * 43758.5453; return s - Math.floor(s); };

// Applies a patch to this script's own copy of the document, so that a later section of the same script sees
// what an earlier one decided, exactly as a separate script would have, without a round trip through the engine.
const mergeInto = (target, patchObject) => {
	for (const k of Object.keys(patchObject)) {
		const v = patchObject[k];
		if (v === null) delete target[k];
		else if (v && typeof v === 'object' && !Array.isArray(v) && target[k] && typeof target[k] === 'object' && !Array.isArray(target[k])) mergeInto(target[k], v);
		else target[k] = (v && typeof v === 'object') ? JSON.parse(JSON.stringify(v)) : v;
	}
};

// ---- game.js
{
// The adventure. Four modes: title, play, menu (the pause menu with its tabs) and talk (a conversation).
// This section decides what mode the game is in, runs the menus, saving and loading, quests, items and
// conversations, and hands what the menus should show to menu.js through X.
const G = dat('game'), P = dat('player'), R = dat('rpg'), D = dat('defs');
const ctlPads = E.packages.controllers.utilities;
const kbd = ctlPads['keyboard-0'], mouse = ctlPads['pointer-0'];
const struck = kbd ? kbd.properties.state.pressed.slice() : [];       // the keys struck this frame; in a headset, the buttons that stand for them are added below
const hitK = (...codes) => codes.some(c => struck.indexOf(c) >= 0);
let clicked = !!mouse && mouse.properties.state.pressed.indexOf('button0') >= 0;
const disp = E.utilities.display.properties.state;
const locked = !!(disp.locked || (disp.xr && disp.xr.presenting));
const now = T.elapsed;
const fmt = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
const copy = o => JSON.parse(JSON.stringify(o || {}));

const g = {};                                         // what changes in the game's own data this frame
const setG = (k, v) => { if (G[k] !== v) g[k] = v; };
let mode = G.mode;

// ---------------------------------------------------------------- the headset
// Everything the keyboard and mouse do has a button of the controllers. Playing:  left stick walk or fly, right stick turn and rise or sink,
// left trigger fly / land, right trigger and right grip the two abilities, left grip run or boost, A talk / take / enter, B jump,
// X inventory, Y map, left stick click the log.  In the menus a hand points at the interface and the trigger clicks; the sticks and
// buttons do the same for anyone who prefers them (stick choose, grips change tab, A select, B resume, X / Y / stick click bind).
const headCam = get('player').packages.head.utilities.camera.properties.state;
const VR = !!(headCam && headCam.presenting);
const RK = VR ? 'A' : 'R';                                  // the key that talks, takes and answers
X.vr = VR;
let vrPtr = null, vrClick = false, vrDown = false, vrRow = null, vrRowClick = null, vrTabHit = -1;
X.vrPad = { lx: 0, ly: 0, rx: 0, ry: 0 };
X.vrEdge = {};                                              // buttons that went down this frame: worked out from what is held, because the engine's own edge list lasts only one tick
if (VR) try {
	const sL = ctlPads['xr-controller-left'] ? ctlPads['xr-controller-left'].properties.state : null;
	const sR = ctlPads['xr-controller-right'] ? ctlPads['xr-controller-right'].properties.state : null;
	const hd = (s, n) => !!s && s.digital.indexOf(n) >= 0;
	const ax = (s, n) => s && s.analog ? (s.analog[n] || 0) : 0;
	const held = { Lt: hd(sL, 'trigger'), Rt: hd(sR, 'trigger'), Lg: hd(sL, 'squeeze'), Rg: hd(sR, 'squeeze'), X: hd(sL, 'a'), Y: hd(sL, 'b'), A: hd(sR, 'a'), B: hd(sR, 'b'), Ls: hd(sL, 'thumbstick'), Rs: hd(sR, 'thumbstick') };
	const prev = G.vrH || {};
	const edge = k => held[k] && !prev[k];
	if (Object.keys(held).some(k => !!held[k] !== !!prev[k])) g.vrH = held;
	for (const k of Object.keys(held)) X.vrEdge[k] = edge(k);
	X.vrPad = { lx: ax(sL, 'thumbstick-x'), ly: ax(sL, 'thumbstick-y'), rx: ax(sR, 'thumbstick-x'), ry: ax(sR, 'thumbstick-y') };
	// the hand that pulled its trigger last is the one that points
	let hand = G.vrHand || 'right';
	if (edge('Lt') && sL) hand = 'left'; else if (edge('Rt') && sR) hand = 'right';
	if (hand !== G.vrHand) g.vrHand = hand;
	const trig = hand === 'left' ? 'Lt' : 'Rt';
	vrDown = !!held[trig]; vrClick = edge(trig);
	// where that hand's ray meets the interface: a plane the overlay's distance in front of the viewer, laid out in tangents (the interface's own units)
	const ps = hand === 'left' ? (sL && sL.local ? sL : sR) : (sR && sR.local ? sR : sL);
	if (ps && ps.local && ps.local.direction[2] < -1e-3) {
		const OV = dat('ui').overlay || 10, o = ps.local.origin, d = ps.local.direction, t = (-OV * 0.967 - o[2]) / d[2];   // the menu is drawn a little nearer than the plane the overlay sits on
		if (t > 0) vrPtr = [(o[0] + t * d[0]) / OV, (o[1] + t * d[1]) / OV];
	}
	// where the right hand's ray meets the heads-up display, for the sight
	if (sR && sR.local && sR.local.direction[2] < -1e-3) {
		const OV = dat('ui').overlay || 10, o = sR.local.origin, d = sR.local.direction, t = (-OV - o[2]) / d[2];
		if (t > 0) X.aimPt = [(o[0] + t * d[0]) / OV, (o[1] + t * d[1]) / OV];
	}
	const mm = G.mode, press = (...c) => c.forEach(k => struck.push(k));
	// a stick pushed to either end chooses, then repeats
	const ny = ax(sL, 'thumbstick-y') || ax(sR, 'thumbstick-y'), dir = ny > 0.6 ? 1 : ny < -0.6 ? -1 : 0;
	const flick = () => {
		if (dir && (dir !== (G.vrDir || 0) || now >= (G.vrNext || 0))) { press(dir > 0 ? 'ArrowUp' : 'ArrowDown'); g.vrNext = now + (dir !== (G.vrDir || 0) ? 0.45 : 0.16); }
		if (dir !== (G.vrDir || 0)) g.vrDir = dir;
	};
	if (mm === 'play') {
		if (edge('A')) press('KeyR');
		if (edge('X')) press('KeyI');
		if (edge('Y')) press('KeyM');
		if (edge('Ls')) press('KeyL');
	} else if (mm === 'talk') {
		if (edge('A')) press('KeyR');
		flick();
	} else if (mm === 'splash') {
		if (edge('A') || edge('Lt') || edge('Rt')) press('Enter');
	} else if (mm === 'title') {
		if (edge('A')) press('Enter');
		flick();
	} else if (mm === 'menu') {
		const onMapTab = (G.tab || 0) === 2;
		if (edge('Lg')) press('KeyQ');
		if (edge('Rg')) press('KeyE');
		if (edge('A')) press(onMapTab ? 'KeyR' : 'Enter');
		if (edge('B')) press('Escape');
		if (edge('X')) press('Digit1');
		if (edge('Y')) press('Digit2');
		if (edge('Ls')) press('Digit3');
		if (!onMapTab) flick();
	}
	// pointing at the list, or at a tab
	if (vrPtr && (mm === 'title' || mm === 'menu')) {
		const UIc = dat('ui'), u = vrPtr[0], v = vrPtr[1], i = Math.round((UIc.top - v) / UIc.step);
		if (u > -1.06 && u < -0.34 && i >= 0 && i < UIc.rows && Math.abs(UIc.top - i * UIc.step - v) < UIc.step / 2) vrRow = i;
		if (mm === 'menu' && v > 0.47 && v < 0.58) for (let k = 0; k < 4; k++) if (Math.abs(u - UIc.tabX[k]) < 0.24) vrTabHit = k;
		if (vrClick) vrRowClick = vrRow;
	}
	if (mm === 'talk' && vrClick) clicked = true;
} catch (e) { g.vrErr = String(e && e.message); }

// working copies of the adventure's state; written back only if something changed
let inv = copy(R.inv), bind = copy(R.bind), q = copy(R.q), flags = copy(R.flags), found = copy(R.found), kills = copy(R.kills);
let dirty = false, autosave = false;
const rep = (cur, next) => { const o = {}; for (const k of Object.keys(cur || {})) if (!(k in next)) o[k] = null; return Object.assign(o, next); };
const sfx = name => { g.sfx = name; };
const note = text => { g.note = text; g.noteTimer = 4.5; };

// ---------------------------------------------------------------- the people and things of the world
const things = Object.keys(get('things').packages).map(id => Object.assign({ id }, dat('things.' + id)));
const itemName = id => (D.items[id] || { name: id }).name;

// ---------------------------------------------------------------- where the player is: out in the world, or inside a building
// Out in the world, each island is switched on only while the player is within reach of it (with a margin, so that it does not flicker on and off at the
// edge): its terrain, plants, monsters, buildings and people are not drawn, streamed or thought about otherwise. Inside a building none of the world
// is: the player is in a room of their own, far from everything, and the outdoors is switched off entirely.
// An island has faded out of the picture (the ground, and the models in `fades`, see below) well before it is switched off, which is why the distance is that to its nearest edge.
const AREA = G.area || 'overworld';
const REACH = G.reach;
const vis = {};
for (const k of ['A', 'B', 'F']) {
	const c = G.isles[k], h = G.isleHalf[k], was = G['vis' + k];
	const d = Math.hypot(Math.max(0, Math.abs(P.position[0] - c[0]) - h), Math.max(0, Math.abs(P.position[2] - c[1]) - h));
	vis[k] = AREA !== 'overworld' ? 0 : d < REACH[k][0] ? 1 : d > REACH[k][1] ? 0 : was;
	if (vis[k] !== was) g['vis' + k] = vis[k];
}
// models that fade as they are left behind: their opacity follows their distance, a little at a time (only a change that can be seen is written)
if (AREA === 'overworld' && T.frame % 3 === 0) for (const f of G.fades) {
	const n = get(f[0]);
	if (!n || !n.utilities || !n.utilities.mesh) continue;
	const d = Math.hypot(f[1] - P.position[0], f[2] - P.position[2]);
	const o = +(1 - clamp((d - f[3]) / (f[4] - f[3]), 0, 1)).toFixed(2), cur = n.utilities.mesh.properties.data.opacity;
	if ((cur === undefined ? 1 : cur) !== o) comp(f[0], 'mesh', { opacity: o });
}
const GROUPS = { A: ['terrain', 'forest', 'flora', 'reef', 'fish', 'landmarks', 'camp', 'enemies'], B: ['isleB'], F: ['isleF'] };
const setOn = (pkg, on) => { const d = dat(pkg); if (d && (d.enabled !== false) !== !!on) put(pkg, { enabled: !!on }); };
for (const k of Object.keys(GROUPS)) for (const pkg of GROUPS[k]) setOn(pkg, vis[k]);
for (const pkg of ['water', 'seabed', 'clouds']) setOn(pkg, AREA === 'overworld');
for (const k of Object.keys(G.rooms)) {
	setOn('rooms.' + k, AREA === k);
	for (const l of ['lightA', 'lightB']) {
		const lu = get('rooms.' + k + '.' + l).utilities.light, now = AREA === k;
		if ((lu.properties.data.on !== false) !== now) comp('rooms.' + k + '.' + l, 'light', { on: now });
	}
}

// ---------------------------------------------------------------- quests
const prog = id => {
	const def = D.quests[id], rec = q[id] || { base: {} };
	return def.objectives.map(o => {
		let have = 0, need = o.need || 1;
		if (o.type === 'have') have = inv[o.item] || 0;
		else if (o.type === 'kill') have = Math.max(0, ((kills[o.kind] || {}).n || 0) - ((rec.base || {})[o.kind] || 0));
		else have = flags[o.flag] ? 1 : 0;
		return { text: o.text, have: Math.min(have, need), need, ok: have >= need, bar: o.type !== 'flag' };
	});
};
const qstate = id => {
	const rec = q[id];
	if (!rec) return 'inactive';
	if (rec.s === 'done') return 'done';
	return prog(id).every(o => o.ok) ? 'ready' : 'active';
};
const startQuest = id => {
	if (q[id]) return;
	const base = {};
	for (const k of Object.keys(D.kinds)) base[k] = (kills[k] || {}).n || 0;
	q[id] = { s: 'active', base, t: now, rn: 0 };
	note('New quest: ' + D.quests[id].title); sfx('quest'); dirty = autosave = true;
};
const completeQuest = id => {
	if (qstate(id) !== 'ready') return;
	const r = D.quests[id].reward || {};
	for (const k of Object.keys(r.items || {})) inv[k] = (inv[k] || 0) + r.items[k];
	if (r.maxHealth) { put('player', { maxHealth: P.maxHealth + r.maxHealth, health: P.maxHealth + r.maxHealth }); }
	q[id].s = 'done';
	note('Quest complete: ' + D.quests[id].title + '   Reward: ' + (r.text || 'none')); sfx('quest'); dirty = autosave = true;
};
const effects = list => {
	for (const e of list || []) {
		if (e[0] === 'start') startQuest(e[1]);
		else if (e[0] === 'complete') completeQuest(e[1]);
		else if (e[0] === 'give') { inv[e[1]] = (inv[e[1]] || 0) + (e[2] || 1); dirty = true; }
		else if (e[0] === 'take') { inv[e[1]] = Math.max(0, (inv[e[1]] || 0) - (e[2] || 1)); dirty = true; }
		else if (e[0] === 'flag') { flags[e[1]] = 1; dirty = true; }
	}
};

// defeated creatures are recorded as they fall (combat reports them in game.kill_<kind>)
for (const kind of Object.keys(D.kinds)) {
	const n = G['kill_' + kind] || 0;
	if (n > 0) { const k = kills[kind] || { n: 0, first: now }; k.n += n; k.last = now; kills[kind] = k; g['kill_' + kind] = 0; dirty = true; }
}
// a quest whose objectives are met says so once
for (const id of Object.keys(q)) {
	const s = qstate(id);
	if (s === 'ready' && !q[id].rn) { q[id].rn = 1; dirty = true; note('Quest updated: ' + D.quests[id].title + '  (return to ' + D.quests[id].giver + ')'); sfx('quest'); }
	else if (s === 'active' && q[id].rn) { q[id].rn = 0; dirty = true; }
}

// ---------------------------------------------------------------- saving and loading
const SLOTS = [0, 1, 2, 3];
const slotName = n => n === 0 ? 'Autosave' : 'Slot ' + n;
const readSlot = n => {
	const u = get('saves.slot' + n).utilities.disk.properties;
	if (!u.state || !u.state.value) return null;
	try { return JSON.parse(u.state.value); } catch (e) { return null; }
};
const snapshot = () => ({
	v: 1, t: Date.now(), play: now, inv, bind, q, flags, found, kills,
	taken: things.filter(t => t.taken).map(t => t.id),
	health: P.health, maxHealth: P.maxHealth, score: G.score, deaths: G.deaths, killsTotal: G.kills,
	pos: P.position, yaw: P.yaw, pitch: P.pitch, flying: P.flying, area: AREA, ret: G.ret
});
const saveSlot = n => {
	const rev = (get('saves.slot' + n).utilities.disk.properties.data.revision || 0) + 1;
	comp('saves.slot' + n, 'disk', { value: JSON.stringify(snapshot()), revision: rev });
};
const describe = s => {
	if (!s) return 'Empty';
	const done = Object.keys(s.q || {}).filter(id => s.q[id].s === 'done').length;
	const defeated = Object.keys(s.kills || {}).reduce((a, k) => a + s.kills[k].n, 0);
	return fmt(s.play || 0) + ' played   ' + done + '/' + Object.keys(D.quests).length + ' quests   ' + defeated + ' defeated' +
		(s.t ? '\n' + new Date(s.t).toLocaleString() : '');
};
const updateThings = takenList => {
	for (const t of things) {
		const gone = takenList.indexOf(t.id) >= 0;
		if (!!t.taken !== gone) put('things.' + t.id, { taken: gone ? 1 : 0 });
	}
};
const writeBack = () => put('rpg', { inv: rep(R.inv, inv), bind: rep(R.bind, bind), q: rep(R.q, q), flags: rep(R.flags, flags), found: rep(R.found, found), kills: rep(R.kills, kills) });
// A game begins, or a saved one is taken up, with the creatures the world starts with and nothing still in flight from before: every monster is put back to be
// brought in again at a lair or a roost (the director does that when its timer runs out), and every bolt, fireball and explosion is stopped.
const resetCreatures = () => {
	g.attend = '';
	// the people go back to where they live, and anyone who was on the way to speak to the player is not
	for (const t of things) if (t.kind === 'npc' && t.ai) put('things.' + t.id, { position: t.home, rotation: [0, t.homeYaw, 0], mv: 'idle', mvT: 2, goal: [t.home[0], t.home[2]], greetAt: -1e9, clip: 'x' });
	g.greet = '';
	Object.keys(get('enemies').packages).forEach((id, n) => put('enemies.' + id, { alive: 0, enabled: false, state: 'patrol', respawn: 0.4 + hash(n * 3.7 + 1) * 3 }));
	for (let i = 0; i < 40; i++) put('shots.s' + i, { enabled: false });
	for (let i = 0; i < 16; i++) put('fire.f' + i, { enabled: false });
	for (let i = 0; i < 10; i++) put('fx.x' + i, { enabled: false });
};
const loadSnapshot = s => {
	inv = copy(s.inv); bind = copy(s.bind); q = copy(s.q); flags = copy(s.flags); found = copy(s.found); kills = copy(s.kills);
	dirty = true;
	updateThings(s.taken || []);
	resetCreatures();
	put('player', {
		position: s.pos, vel: [0, 0, 0], vy: 0, flying: s.flying ? 1 : 0, health: s.health, maxHealth: s.maxHealth, dead: 0,
		yaw: s.yaw, pitch: s.pitch, roll: 0, boost: 1, hurt: 0, tele: 5
	});
	g.kills = s.killsTotal || 0; g.score = s.score || 0; g.deaths = s.deaths || 0;
	g.area = s.area || 'overworld'; if (s.ret) g.ret = s.ret;
	note('Game loaded');
};
const newGame = () => {
	inv = { bolt: 1 }; bind = { l: 'bolt', r: '' }; q = {}; flags = {}; found = { camp: 1 }; kills = {};
	dirty = true;
	updateThings([]);
	resetCreatures();
	put('player', {
		position: G.spawn, vel: [0, 0, 0], vy: 0, flying: 0, health: 100, maxHealth: 100, dead: 0,
		yaw: G.spawnYaw, pitch: 0, roll: 0, boost: 1, hurt: 0, tele: 5
	});
	g.kills = 0; g.score = 0; g.deaths = 0; g.area = 'overworld';
	note('Speak to Maren, by the fire.');
	autosave = true;
};

// ---------------------------------------------------------------- the interface's views, built per mode
const nav = (n) => {
	let sel = G.sel || 0;
	// a hand that moves onto a row chooses it; the trigger on a row uses it
	if (VR) {
		const seen = vrRow !== null && vrRow < n ? vrRow : -1;
		if (seen !== (G.vrRowSeen === undefined ? -1 : G.vrRowSeen)) { g.vrRowSeen = seen; if (seen >= 0 && seen !== sel) { sel = seen; sfx('click'); } }
		if (vrRowClick !== null && vrRowClick < n) { sel = vrRowClick; struck.push('Enter'); }
	}
	if (hitK('ArrowDown', 'KeyS')) { sel = (sel + 1) % Math.max(1, n); sfx('click'); }
	if (hitK('ArrowUp', 'KeyW')) { sel = (sel + n - 1) % Math.max(1, n); sfx('click'); }
	return clamp(sel, 0, Math.max(0, n - 1));
};
const ABIL = Object.keys(D.abilities);
const bindMark = id => (bind.l === id ? 'L' : '') + (bind.r === id ? 'R' : '');

const inventoryRows = () => {
	const rows = [];
	for (const id of Object.keys(D.items)) {
		if (!(inv[id] > 0)) continue;
		const it = D.items[id];
		if (it.type === 'ability') {
			const m = bindMark(id);
			rows.push({ id, label: it.name + (m ? '      [' + (VR ? (m === 'LR' ? 'TRIGGER GRIP' : m === 'L' ? 'TRIGGER' : 'GRIP') : (m === 'LR' ? 'LMB RMB' : m === 'L' ? 'LMB' : 'RMB')) + ']' : ''), detail: it.name + '\n\n' + it.desc + '\n\n' + (VR ? 'Press X to place it on the trigger, Y for the grip, left stick click to clear it.' : 'Press 1 to place it on the left mouse button, 2 for the right, 3 to clear it.') });
		} else {
			rows.push({ id, label: it.name + '      x' + inv[id], detail: it.name + '\n\n' + it.desc + (it.heal ? '\n\n' + (VR ? 'Press A, or pull the trigger on it, to use it.' : 'Press Enter to use it.') : '') });
		}
	}
	return rows;
};
const questRows = () => {
	const rows = [{ label: '-  QUESTS  -', detail: 'What you have taken on, and what is left to do. Quests ready to hand in are listed first.' }], order = { ready: 0, active: 1, done: 2 };
	const ids = Object.keys(q).sort((a, b) => order[qstate(a)] - order[qstate(b)] || q[a].t - q[b].t);
	for (const id of ids) {
		const def = D.quests[id], s = qstate(id);
		const lines = prog(id).map(o => (o.ok ? '-   ' : '•   ') + o.text + (o.bar ? '   ' + o.have + ' / ' + o.need : ''));
