	}
}

for (const k of Object.keys(fell)) put('game', { ['kill_' + k]: (G['kill_' + k] || 0) + fell[k] });
if (hitEvents) put('game', { hitEvent: 1, hitMark: 0.16 });
if (kills) put('game', { kills: G.kills + kills, score: G.score + score });
